//! SHA-256 XZ interoperability and corruption regression for the TRUEOS dependency port.
//! Fixture produced by Python/liblzma with FORMAT_XZ and CHECK_SHA256.
use std::io::Read;
use lzma_rust2::XzReader;

const PAYLOAD: &[u8] = b"TRUEOS XZ SHA-256 validation fixture\n";
const STREAM: &[u8] = &[
    0xfd, 0x37, 0x7a, 0x58, 0x5a, 0x00, 0x00, 0x0a, 0xe1, 0xfb, 0x0c, 0xa1, 0x02, 0x00, 0x21, 0x01,
    0x16, 0x00, 0x00, 0x00, 0x74, 0x2f, 0xe5, 0xa3, 0x01, 0x00, 0x24, 0x54, 0x52, 0x55, 0x45, 0x4f,
    0x53, 0x20, 0x58, 0x5a, 0x20, 0x53, 0x48, 0x41, 0x2d, 0x32, 0x35, 0x36, 0x20, 0x76, 0x61, 0x6c,
    0x69, 0x64, 0x61, 0x74, 0x69, 0x6f, 0x6e, 0x20, 0x66, 0x69, 0x78, 0x74, 0x75, 0x72, 0x65, 0x0a,
    0x00, 0x00, 0x00, 0x00, 0x12, 0x27, 0xf9, 0x9b, 0xf7, 0xf6, 0x47, 0x17, 0x6f, 0xe2, 0xf1, 0x9f,
    0xcc, 0x24, 0xa7, 0x30, 0xbc, 0x23, 0xf5, 0x0d, 0xe1, 0xd3, 0x80, 0x8e, 0x82, 0x01, 0x85, 0x96,
    0xe6, 0xf7, 0x46, 0x6a, 0x00, 0x01, 0x55, 0x25, 0x7d, 0xc8, 0x4e, 0xac, 0x18, 0x9b, 0x4b, 0x9a,
    0x01, 0x00, 0x00, 0x00, 0x00, 0x0a, 0x59, 0x5a,
];

#[test]
fn external_xz_sha256_stream_decodes() {
    let mut reader = XzReader::new(STREAM, false);
    let mut output = Vec::new();
    reader.read_to_end(&mut output).unwrap();
    assert_eq!(output, PAYLOAD);
}

#[test]
fn external_xz_sha256_stream_rejects_corrupt_checksum() {
    let mut corrupt = STREAM.to_vec();
    // Corrupt the block's SHA-256 digest, leaving encoded payload/header/index intact.
    corrupt[68] ^= 1;
    let mut reader = XzReader::new(corrupt.as_slice(), false);
    let mut output = Vec::new();
    let error = reader.read_to_end(&mut output).unwrap_err();
    assert_eq!(error.kind(), std::io::ErrorKind::InvalidData);
    assert_eq!(error.to_string(), "invalid block checksum");
}
